def section(text, heading):
    match = re.search(rf"^## {re.escape(heading)}\n(?P<body>.*?)(?=^## |\Z)", text, re.M | re.S)
    assert match
    return match.group("body")


def numbered(body):
    return re.findall(r"^\d+\. `([^`]+)`$", body, re.M)


def table(body):
    return [tuple(cell.strip().strip("`") for cell in line.strip("|").split("|")) for line in body.splitlines() if line.startswith("|") and "---" not in line][1:]


def test_exact_document_title_id_headings_and_complete_bodies():
    text = DOC_PATH.read_text(encoding="utf-8")
    assert text == EXPECTED_DOC
    assert text.startswith("# WEATHER-BOT-STAGE3-SCORING-AND-DIAGNOSTICS-IMPLEMENTATION-APPROVAL-REQUEST-01\n\nCanonical ID: WEATHER-BOT-STAGE3-SCORING-AND-DIAGNOSTICS-IMPLEMENTATION-APPROVAL-REQUEST-01")
    assert [x[3:] for x in text.splitlines() if x.startswith("## ")] == EXPECTED_HEADINGS
    assert len(EXPECTED_HEADINGS) == 29
    assert all(section(text, heading).strip() for heading in EXPECTED_HEADINGS)


