    assert [row[2] for row in enums[:8]] == EXPECTED_ARTIFACTS
    assert [row[2] for row in enums[8:11]] == EXPECTED_REPRESENTATIONS
    assert enums[11:] == [("ScoringDefinitionStatus", "ACTIVE", "active"), ("ScoringDefinitionStatus", "BLOCKED", "blocked"), ("ScoringValidationSeverity", "PASSED", "passed"), ("ScoringValidationSeverity", "BLOCKED", "blocked")]
    assert table(section(EXPECTED_DOC, "Representation matrix")) == [
        ("brier_score","binary_outcome_probability","lower_is_better"), ("log_score","binary_outcome_probability","lower_is_better"),
        ("reliability_diagram","binary_outcome_probability","diagnostic_only_not_scalar_ranking"), ("brier_decomposition","binary_outcome_probability","diagnostic_only_not_scalar_ranking"),
        ("crps","full_predictive_distribution","lower_is_better"), ("pit_histogram","full_predictive_distribution","diagnostic_only_not_scalar_ranking"),
        ("rank_histogram","finite_comparable_ensemble","diagnostic_only_not_scalar_ranking"), ("threshold_weighted_crps","full_predictive_distribution","lower_is_better")]
    assert len(table(section(EXPECTED_DOC, "Artifact-policy matrix"))) == 8
    assert len(table(section(EXPECTED_DOC, "Fixed postures"))) == 12


