def test_codes_decisions_assignments_and_targeted_mutations():
    code_items = numbered(section(EXPECTED_DOC, "Validation codes"))
    assert [item.split(" = ")[0] for item in code_items] == EXPECTED_CODES
    assert [item.split('"')[1] for item in code_items] == [x.lower() for x in EXPECTED_CODES]
    assert numbered(section(EXPECTED_DOC, "Decision options and current status")) == EXPECTED_DECISIONS
    assignments = section(EXPECTED_DOC, "Machine assignments")
    for literal in ["public_symbol_count: `9`", "definition_field_count: `37`", "required_mapping_key_count: `36`", "validation_code_count: `24`"]:
        assert literal in assignments
    for heading in ["Enums", "Fixed postures", "Representation matrix", "Artifact-policy matrix"]:
        body = section(EXPECTED_DOC, heading)
        mutated = body.replace("brier_score", "mutated", 1) if "brier_score" in body else body.replace("not_approved", "approved", 1)
        assert mutated != body
        assert mutated not in EXPECTED_DOC


def test_non_goals_and_static_test_safety():
    non_goals = section(EXPECTED_DOC, "Non-goals")
    for item in ["score calculation", "diagnostic calculation", "probability generation", "label joining", "split execution", "baseline execution", "evaluation-result creation", "claim creation or evaluation", "evidence-gate evaluation", "data or corpus creation", "source fetching", "persistence", "reporting", "simulation", "market comparison execution", "trading", "runtime orchestration", "autonomy"]:
        assert item in non_goals
    tree = ast.parse(SELF_PATH.read_text(encoding="utf-8"))
    imports = {node.names[0].name.split(".")[0] for node in tree.body if isinstance(node, (ast.Import, ast.ImportFrom))}
    assert imports <= {"ast", "pathlib", "re"}
    forbidden = {"open", "exec", "eval", "compile", "__import__", "system", "popen", "run", "check_call", "check_output", "putenv", "setenv"}
    calls = {node.func.id for node in ast.walk(tree) if isinstance(node, ast.Call) and isinstance(node.func, ast.Name)}
    assert not calls & forbidden


def test_direct_allowlist_registration_and_observed_counts():
    source = ALLOWLIST_PATH.read_text(encoding="utf-8")
    tree = ast.parse(source)
    assignment = next(node for node in tree.body if isinstance(node, ast.AnnAssign) and isinstance(node.target, ast.Name) and node.target.id == "ALLOWED_MARKET_ID_OCCURRENCE_LINES")
    assert isinstance(assignment.value, ast.Call) and len(assignment.value.args) == 1
    allowlist = ast.literal_eval(assignment.value.args[0])
    for path, count in EXPECTED_ALLOWLIST_COUNTS.items():
        assert allowlist[path] == count
        assert (ROOT / path).read_text(encoding="utf-8").count("market_id") == count
